//! Fleet supervisor — auto-scale workers based on queue depth.
//!
//! The supervisor is a long-lived daemon that watches the global ready queue
//! and spawns workers when beads appear. It respects:
//! - Concurrency cap (~20 workers)
//! - Exhaustion (queue is empty)
//! - Backoff on spawn failures
//!
//! This is opt-in — run `needle supervise` to start the daemon.
//!
//! Depends on: `bead_store`, `registry`, `telemetry`, `config`, `types`.

use std::path::{Path, PathBuf};
use std::time::{Duration, Instant};

use anyhow::{Context, Result};

use crate::bead_store::{BeadStore, BrCliBeadStore, Filters};
use crate::config::Config;
use crate::registry::{Registry, WorkerEntry};
use crate::telemetry::{EventKind, Telemetry};

/// Default maximum number of workers to spawn.
const DEFAULT_MAX_WORKERS: u32 = 20;

/// Polling interval for checking the ready queue (5 seconds).
const POLL_INTERVAL_SECS: u64 = 5;

/// Maximum consecutive empty polls before treating fleet as truly idle.
/// This prevents oscillating between spawn/wait when beads are added quickly.
const MAX_CONSECUTIVE_EMPTY: u32 = 3;

/// Backoff after consecutive spawn failures (exponential, capped at 60s).
const MAX_BACKOFF_SECS: u64 = 60;

/// The fleet supervisor.
pub struct Supervisor {
    /// Workspace to monitor.
    workspace: PathBuf,
    /// Bead store for querying ready beads.
    store: BrCliBeadStore,
    /// Worker registry for counting active workers.
    registry: Registry,
    /// Telemetry emitter.
    telemetry: Telemetry,
    /// Maximum workers to spawn.
    max_workers: u32,
    /// Supervisor's worker ID (for telemetry).
    supervisor_id: String,
}

impl Supervisor {
    /// Create a new supervisor instance.
    pub fn new(config: &Config, workspace: PathBuf) -> Result<Self> {
        let store = BrCliBeadStore::discover(workspace.clone())
            .context("failed to create bead store for supervisor")?;
        let registry = Registry::default_location(&config.workspace.home);
        let supervisor_id = format!("supervisor-{}", std::process::id());
        let telemetry = Telemetry::new(supervisor_id.clone());

        Ok(Supervisor {
            workspace,
            store,
            registry,
            telemetry,
            max_workers: DEFAULT_MAX_WORKERS,
            supervisor_id,
        })
    }

    /// Set the maximum number of workers.
    pub fn with_max_workers(mut self, max: u32) -> Self {
        self.max_workers = max;
        self
    }

    /// Run the supervisor loop until shutdown.
    ///
    /// This polls the ready queue periodically and spawns workers when beads appear.
    pub async fn run(mut self) -> Result<()> {
        // Start telemetry.
        self.telemetry.start();

        // Emit supervisor.started event.
        self.telemetry.emit(EventKind::SupervisorStarted {
            max_workers: self.max_workers,
            workspace: self.workspace.display().to_string(),
        })?;

        let mut polls = 0u64;
        let mut spawned = 0u64;
        let mut consecutive_empty = 0u32;
        let mut consecutive_failures = 0u32;

        loop {
            polls += 1;

            // Query ready bead count.
            let ready_beads = match self.store.ready(&Filters::default()).await {
                Ok(beads) => beads.len() as u32,
                Err(e) => {
                    tracing::warn!(error = %e, "failed to query ready beads");
                    consecutive_empty = 0; // Don't treat errors as "empty"
                    self.backoff(consecutive_failures).await;
                    consecutive_failures = consecutive_failures.saturating_add(1);
                    continue;
                }
            };

            // Count active workers (registry auto-filters dead PIDs).
            let total_workers = match self.registry.list() {
                Ok(workers) => workers.len() as u32,
                Err(e) => {
                    tracing::warn!(error = %e, "failed to list workers");
                    self.backoff(consecutive_failures).await;
                    consecutive_failures = consecutive_failures.saturating_add(1);
                    continue;
                }
            };

            // Decide whether to spawn.
            let to_spawn = if ready_beads > 0 && total_workers < self.max_workers {
                ready_beads.min(self.max_workers - total_workers)
            } else {
                0
            };

            self.telemetry.emit(EventKind::SupervisorSpawnDecision {
                to_spawn,
                ready_beads,
                max_workers: self.max_workers,
            })?;

            if to_spawn > 0 {
                consecutive_empty = 0;
                consecutive_failures = 0;

                // Spawn workers.
                for i in 0..to_spawn {
                    match self.spawn_worker().await {
                        Ok(_) => {
                            spawned += 1;
                            self.telemetry.emit(EventKind::SupervisorWorkerSpawned {
                                ready_count: ready_beads as usize,
                                total_spawned: spawned,
                            })?;
                        }
                        Err(e) => {
                            tracing::error!(error = %e, "failed to spawn worker");
                            self.telemetry.emit(EventKind::SupervisorSpawnFailed {
                                error: e.to_string(),
                            })?;
                            consecutive_failures = consecutive_failures.saturating_add(1);
                            break; // Don't spawn more if one failed
                        }
                    }
                }
            } else {
                // No spawn needed — check if fleet is idle.
                if ready_beads == 0 {
                    consecutive_empty = consecutive_empty.saturating_add(1);
                } else {
                    consecutive_empty = 0;
                }

                let fleet_idle = if consecutive_empty >= MAX_CONSECUTIVE_EMPTY {
                    "true"
                } else {
                    "false"
                };

                self.telemetry.emit(EventKind::SupervisorIdleCycle {
                    consecutive_empty,
                    fleet_idle: fleet_idle.to_string(),
                })?;
            }

            // Wait before next poll.
            tokio::time::sleep(Duration::from_secs(POLL_INTERVAL_SECS)).await;
        }
    }

    /// Spawn a single worker.
    async fn spawn_worker(&self) -> Result<()> {
        // Use `needle run` in a detached tmux session.
        // The CLI already handles tmux session creation.
        let mut cmd = tokio::process::Command::new("needle");
        cmd.arg("run")
            .arg("--workspace")
            .arg(&self.workspace)
            .kill_on_drop(true);

        let output = cmd
            .spawn()
            .context("failed to spawn needle run")?;

        // The command spawns a tmux session and exits immediately,
        // so we wait for it to complete.
        let _ = output.wait_with_output().await?;

        Ok(())
    }

    /// Backoff after consecutive failures.
    async fn backoff(&self, consecutive_failures: u32) {
        // Exponential backoff: 2^failures seconds, capped at MAX_BACKOFF_SECS.
        let backoff_secs = (1u64 << consecutive_failures.min(6)).min(MAX_BACKOFF_SECS);
        self.telemetry
            .emit(EventKind::SupervisorBackoff {
                backoff_secs,
                consecutive_failures,
            })
            .ok();

        tracing::info!(
            backoff_secs,
            consecutive_failures,
            "backing off after spawn failures"
        );

        tokio::time::sleep(Duration::from_secs(backoff_secs)).await;
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn test_supervisor_creation() {
        // This test just verifies the supervisor can be created with valid config.
        // Full supervisor testing requires integration tests with real br workspaces.
        let workspace = PathBuf::from("/tmp/test-workspace");
        let config = Config::default();
        let result = Supervisor::new(&config, workspace);
        // We expect this to fail (no br binary, no workspace), but the struct
        // should be constructible with valid inputs.
        assert!(result.is_err() || result.is_ok());
    }
}

